// Pick the recommended scan + icon based on triage state. FROM v2
// runLegalReview line 17371-17400 (the eliRecommendBox logic). Pure
// projection — view just renders the strings.

engine.recommendScan:
function recommendScan(input) {
  var isRedline = !!input.isRedline;
  var paperType = String(input.paperType || "thirdparty");
  var hasPlaybook = !!input.hasPlaybook;
  var hasTemplate = !!input.hasTemplate;
  var lines = [];
  var icon = "💡";
  if (isRedline) {
    if (paperType === "thirdparty") {
      lines.push('<strong>Review Redlines</strong> <span class="_eli3_lr_dim">(Playbook disabled)</span>');
    } else if (hasPlaybook) {
      icon = "📗";
      lines.push('<strong>Review Redlines</strong> <span class="_eli3_lr_dim">(with Playbook)</span>');
    } else {
      lines.push("<strong>Review Redlines</strong>");
    }
  } else {
    if (paperType === "colgate") {
      lines.push("<strong>Legal Risks</strong> scan");
      icon = "🛡️";
    } else if (hasTemplate) {
      icon = "⚖️";
      lines.push('<strong>Legal Risks</strong> + <strong>Compare</strong> <span class="_eli3_lr_dim">(matched)</span>');
    } else {
      icon = "🛡️";
      lines.push('<strong>Legal Risks</strong> scan <span class="_eli3_lr_dim">(no template)</span>');
    }
  }
  return { icon: icon, lines: lines };
}

